import React, { useEffect, useState, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import {
  FiLayout, FiTrash2, FiMic, FiVideoOff,
  FiActivity, FiUserCheck, FiUserX
} from 'react-icons/fi';
import confetti from 'canvas-confetti';

import TaskCard from '../components/TaskCard';
import Visualizer from './Visualizer';
import { fetchTasks, updateTask, deleteTask } from '../services/plannerService';

/* ------------------ HELPER: Warning Beep ------------------ */
const playWarningBeep = () => {
  const ctx = new (window.AudioContext || window.webkitAudioContext)();
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = 'sawtooth';
  osc.frequency.value = 800;
  osc.connect(gain);
  gain.connect(ctx.destination);
  osc.start();
  gain.gain.exponentialRampToValueAtTime(0.00001, ctx.currentTime + 0.3);
  osc.stop(ctx.currentTime + 0.3);
};

/* ------------------ NOISE MONITOR ------------------ */
const NoiseMonitor = () => {
  const [volume, setVolume] = useState(35);
  const [isNoisy, setIsNoisy] = useState(false);
  const lastVolume = useRef(35);

  useEffect(() => {
    let ctx, analyser, mic, processor;

    const start = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        ctx = new (window.AudioContext || window.webkitAudioContext)();
        analyser = ctx.createAnalyser();
        mic = ctx.createMediaStreamSource(stream);
        processor = ctx.createScriptProcessor(2048, 1, 1);

        mic.connect(analyser);
        analyser.connect(processor);
        processor.connect(ctx.destination);

        processor.onaudioprocess = () => {
          const data = new Uint8Array(analyser.frequencyBinCount);
          analyser.getByteFrequencyData(data);
          const avg = data.reduce((a, b) => a + b, 0) / data.length;
          const target = avg * 1.5 + 30 + (Math.random() * 4 - 2);
          const smooth = lastVolume.current * 0.8 + target * 0.2;
          lastVolume.current = smooth;
          const finalVol = Math.floor(smooth);
          setVolume(finalVol);
          setIsNoisy(finalVol > 65);
        };
      } catch {
        console.warn('Microphone access denied');
      }
    };

    start();
    return () => ctx && ctx.close();
  }, []);

  return (
    <div className={`p-4 rounded-xl border flex items-center gap-4
      ${isNoisy ? 'bg-red-50 border-red-200' : 'bg-emerald-50 border-emerald-200'}`}>
      <div className={`p-3 rounded-full ${isNoisy ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>
        <FiMic size={24} />
      </div>
      <div>
        <h3 className="font-bold">Noise Level</h3>
        <span className="text-2xl font-mono font-bold">{volume} dB</span>
        <p className="text-sm font-semibold">
          {isNoisy ? '⚠️ Too Loud' : '✅ Good Focus'}
        </p>
      </div>
    </div>
  );
};

/* ------------------ PRESENCE MONITOR ------------------ */
const PresenceMonitor = () => {
  const [status, setStatus] = useState('good');
  const [message, setMessage] = useState('Active & Focused');
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const lastPixels = useRef(null);

  useEffect(() => {
    let stream, interval;

    const start = async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({ video: true });
        videoRef.current.srcObject = stream;
        interval = setInterval(check, 1000);
      } catch {
        setStatus('bad');
        setMessage('Camera Access Denied');
      }
    };

    const check = () => {
      const ctx = canvasRef.current.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0, 320, 240);
      const pixels = ctx.getImageData(0, 0, 320, 240).data;

      let brightness = 0;
      for (let i = 0; i < pixels.length; i += 4)
        brightness += (pixels[i] + pixels[i + 1] + pixels[i + 2]) / 3;

      if (brightness / (pixels.length / 4) < 10) {
        setStatus('bad');
        setMessage('Camera Covered');
        playWarningBeep();
        return;
      }

      if (lastPixels.current) {
        let diff = 0;
        for (let i = 0; i < pixels.length; i += 40)
          diff += Math.abs(pixels[i] - lastPixels.current[i]);

        if (diff < 2000) {
          setStatus('warning');
          setMessage('No Movement Detected');
        } else {
          setStatus('good');
          setMessage('Face Detected');
        }
      }
      lastPixels.current = pixels;
    };

    start();
    return () => {
      stream && stream.getTracks().forEach(t => t.stop());
      interval && clearInterval(interval);
    };
  }, []);

  const icon =
    status === 'good' ? <FiUserCheck /> :
    status === 'warning' ? <FiUserX /> :
    <FiVideoOff />;

  return (
    <div className="p-4 rounded-xl border bg-gray-50 flex gap-4 items-center">
      <video ref={videoRef} autoPlay muted className="hidden" />
      <canvas ref={canvasRef} className="hidden" width="320" height="240" />
      <div className="p-3 rounded-full bg-indigo-100 text-indigo-600">{icon}</div>
      <div>
        <h3 className="font-bold">Proctor Monitor</h3>
        <p className="font-semibold">{message}</p>
      </div>
    </div>
  );
};

/* ------------------ MAIN DASHBOARD ------------------ */
const Dashboard = () => {
  const navigate = useNavigate();
  const [tasks, setTasks] = useState([]);
  const [userName, setUserName] = useState('');

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (!token) navigate('/login');
    setUserName(localStorage.getItem('userName') || 'Student');
    loadTasks();
  }, [navigate]);

  const loadTasks = async () => setTasks(await fetchTasks());

  const completeTask = async (id) => {
    await updateTask(id, { isCompleted: true });
    setTasks(t => t.map(x => x._id === id ? { ...x, isCompleted: true } : x));
    confetti();
  };

  const removeTask = async (id) => {
    await deleteTask(id);
    setTasks(t => t.filter(x => x._id !== id));
  };

  const filter = p => tasks.filter(t => t.priority === p && !t.isCompleted);

  return (
    <div className="p-6 space-y-8 bg-gray-50 min-h-screen">
      <h1 className="text-2xl font-bold">Welcome, {userName} 👋</h1>

      <section>
        <h2 className="text-xl font-bold flex gap-2"><FiActivity /> Smart Proctoring</h2>
        <div className="grid md:grid-cols-2 gap-6 mt-4">
          <NoiseMonitor />
          <PresenceMonitor />
        </div>
      </section>

      <section>
        <h2 className="text-xl font-bold flex gap-2"><FiLayout /> Priority Matrix</h2>
        <div className="grid md:grid-cols-2 gap-6 mt-4">
          {['do_first', 'schedule', 'delegate', 'delete'].map(p => (
            <div key={p} className="space-y-3">
              {filter(p).map(t => (
                <TaskCard
                  key={t._id}
                  task={t}
                  onComplete={completeTask}
                  onDelete={removeTask}
                />
              ))}
            </div>
          ))}
        </div>
      </section>

      <section>
        <h2 className="text-xl font-bold">Quick Practice</h2>
        <Visualizer />
      </section>
    </div>
  );
};

export default Dashboard;
